{"Intent":"Deduplicate Content-Type parsing in the request helpers.","Target":"dba63fa5901fe617d624dc0518cfa6031a1f2301","Head":"547511b68f90b008b8ed8784b31548e0f2b3dcd6","Diff":"diff --git a/server/headers.go b/server/headers.go
index 6c7d484..79c781a 100644
--- a/server/headers.go
+++ b/server/headers.go
@@ -7,18 +7,19 @@ import (

 // IsJSON reports whether the request body is JSON.
 func IsJSON(r *http.Request) bool {
-	ct := r.Header.Get("Content-Type")
-	if i := strings.IndexByte(ct, ';'); i >= 0 {
-		ct = ct[:i]
-	}
-	return strings.EqualFold(strings.TrimSpace(ct), "application/json")
+	return mediaType(r) == "application/json"
 }

 // IsForm reports whether the request body is a URL-encoded form.
 func IsForm(r *http.Request) bool {
+	return mediaType(r) == "application/x-www-form-urlencoded"
+}
+
+// mediaType returns the lower-case Content-Type without parameters.
+func mediaType(r *http.Request) string {
 	ct := r.Header.Get("Content-Type")
 	if i := strings.IndexByte(ct, ';'); i >= 0 {
 		ct = ct[:i]
 	}
-	return strings.EqualFold(strings.TrimSpace(ct), "application/x-www-form-urlencoded")
+	return strings.ToLower(strings.TrimSpace(ct))
 }
